(7022057, 1064669, 65234, '<td valign="top">A post-industrial apocalyptic fly!  Feels like that, anyway.  Very different pose and environment for a macro fly shot.  Wich makes it quite interesting!  A bit too dark in some ways but since that fits the mood of the image it works for me.</td>', 'A post-industrial apocalyptic fly!  Feels like that, anyway.  Very different pose and environment for a macro fly shot.  Wich makes it quite interesting!  A bit too dark in some ways but since that fits the mood of the image it works for me.', '2013-04-17 10:08:59.000000', NULL, 1),
(7022059, 1063970, 65234, '<td valign="top">Too early for dragonflies here :-(. Any day now, though!  Beautiful colors and bokeh to set him off.  Not an ultra-close macro but a very nice image.</td>', 'Too early for dragonflies here :-(. Any day now, though!  Beautiful colors and bokeh to set him off.  Not an ultra-close macro but a very nice image.', '2013-04-17 10:10:13.000000', NULL, 1),
