(7022065, 1064723, 65234, '<td valign="top">Beautifully isolated from his background, but I still get a sense of his environment.  Nicely done.</td>', 'Beautifully isolated from his background, but I still get a sense of his environment.  Nicely done.', '2013-04-17 10:15:15.000000', NULL, 1),
(7022069, 1064451, 124190, '<td valign="top">That''s my speed. :-)</td>', 'That''s my speed. :-)', '2013-04-17 10:21:45.000000', NULL, 1),
(7022070, 1064690, 124815, '<td valign="top">A bud with high aspirations. In a different life he was a prince. Now, a beautiful painting</td>', 'A bud with high aspirations. In a different life he was a prince. Now, a beautiful painting', '2013-04-17 10:25:09.000000', NULL, 1),
(7022074, 1064662, 124815, '<td valign="top">It''s more like a ballad. A stanza and the same sad refrain telling of old battles and lost love</td>', 'It''s more like a ballad. A stanza and the same sad refrain telling of old battles and lost love', '2013-04-17 10:30:04.000000', NULL, 1),
(7022081, 1064451, 65234, '<td valign="top">Punny ;-). Nice light.</td>', 'Punny ;-). Nice light.', '2013-04-17 10:32:25.000000', NULL, 1),
(7022083, 1064560, 65234, '<td valign="top">Not something I would value highly, but I''m not a ladybug.  Looks sort of like it''s been wrapped up by a spider, in which case the ladybug may be in a very bad place.</td>', 'Not something I would value highly, but I''m not a ladybug.  Looks sort of like it''s been wrapped up by a spider, in which case the ladybug may be in a very bad place.', '2013-04-17 10:33:29.000000', NULL, 1),
(7022085, 1064564, 65234, '<td valign="top">The soft light and the bokeh make this image work for me.</td>', 'The soft light and the bokeh make this image work for me.', '2013-04-17 10:33:58.000000', NULL, 1),
(7022087, 1064280, 65234, '<td valign="top">In a very slowly fought war, no doubt.  Major obstacle course he has to get through.  Not an easy life, being a snail.</td>', 'In a very slowly fought war, no doubt.  Major obstacle course he has to get through.  Not an easy life, being a snail.', '2013-04-17 10:34:50.000000', NULL, 1),
(7022088, 1064307, 65234, '<td valign="top">The spots in the lily are such a great background for the ladybug.  Bet this would look nice in B&amp;W, too.</td>', 'The spots in the lily are such a great background for the ladybug.  Bet this would look nice in B&W, too.', '2013-04-17 10:35:53.000000', NULL, 1),
(7022089, 1064709, 65234, '<td valign="top">Like the light/darkness.</td>', 'Like the light/darkness.', '2013-04-17 10:36:24.000000', NULL, 1),
(7022091, 1064353, 65234, '<td valign="top">Fairly astonishing detail.</td>', 'Fairly astonishing detail.', '2013-04-17 10:36:55.000000', NULL, 1),
(7022092, 1063978, 65234, '<td valign="top">Does that mean it tastes better? Not that I am actually inclined to eat the poor thing.</td>', 'Does that mean it tastes better? Not that I am actually inclined to eat the poor thing.', '2013-04-17 10:38:05.000000', NULL, 1),
(7022093, 1064275, 65234, '<td valign="top">Very close, indeed.  Personally, I''d like the head just a bit more in focus, but it''s a very nice image.</td>', 'Very close, indeed.  Personally, I''d like the head just a bit more in focus, but it''s a very nice image.', '2013-04-17 10:39:08.000000', NULL, 1),
(7022098, 1064287, 65234, '<td valign="top">Seems a bit over saturated and focus is sharpest on the eye farther from me, but ... it works, anyway.  My attention is inexorably drawn to that bright little fly.  He better hope there are no predators nearby!</td>', 'Seems a bit over saturated and focus is sharpest on the eye farther from me, but ... it works, anyway.  My attention is inexorably drawn to that bright little fly.  He better hope there are no predators nearby!', '2013-04-17 10:44:05.000000', NULL, 1),
(7022099, 1064586, 65234, '<td valign="top">Love your title :-).   Nice peek into a bug''s life.</td>', 'Love your title :-).   Nice peek into a bug''s life.', '2013-04-17 10:44:47.000000', NULL, 1),
(7022101, 1064182, 65234, '<td valign="top">Awesome spider!  Great DOF and I like the relatively monochrome look.  DOF is spot on.</td>', 'Awesome spider!  Great DOF and I like the relatively monochrome look.  DOF is spot on.', '2013-04-17 10:45:51.000000', NULL, 1),
(7022104, 1064303, 65234, '<td valign="top">Nicely done.  I''d probably crop tighter and try to get the drop more on a ROT line.</td>', 'Nicely done.  I''d probably crop tighter and try to get the drop more on a ROT line.', '2013-04-17 10:47:34.000000', NULL, 1),
(7022106, 1064513, 65234, '<td valign="top">Cute shot, but not close enough for my understanding of a macro.</td>', 'Cute shot, but not close enough for my understanding of a macro.', '2013-04-17 10:50:25.000000', NULL, 1),
(7022108, 1064512, 65234, '<td valign="top">Nice, but not close enough for my understanding of a macro.</td>', 'Nice, but not close enough for my understanding of a macro.', '2013-04-17 10:50:57.000000', NULL, 1),
(7022109, 1064722, 65234, '<td valign="top">Seriously magnified view of a flower!  I find myself wanting a bit more DOF, I think, but I am very impressed to see so much detail on a grain of pollen.</td>', 'Seriously magnified view of a flower!  I find myself wanting a bit more DOF, I think, but I am very impressed to see so much detail on a grain of pollen.', '2013-04-17 10:54:04.000000', NULL, 1),
(7022110, 1064268, 65234, '<td valign="top">I like the DOF, but I''m having a little trouble with the sharpness.  It almost seems like it was slightly OOF and the sharpening was all in PP.</td>', 'I like the DOF, but I''m having a little trouble with the sharpness.  It almost seems like it was slightly OOF and the sharpening was all in PP.', '2013-04-17 10:56:12.000000', NULL, 1),
(7022111, 1064521, 65234, '<td valign="top">Very summery feeling,  I think for this challenge I''d have gone in even closer.</td>', 'Very summery feeling,  I think for this challenge I''d have gone in even closer.', '2013-04-17 10:57:18.000000', NULL, 1),
(7022112, 1064435, 65234, '<td valign="top">This may not work for everyone, but I rather like the light and softness.  Daffodils have been done so often it''s hard to find a new way of presenting them.</td>', 'This may not work for everyone, but I rather like the light and softness.  Daffodils have been done so often it''s hard to find a new way of presenting them.', '2013-04-17 10:58:30.000000', NULL, 1),
(7022114, 1064730, 65234, '<td valign="top">Such a tiny bug!  he might benefit from a bit of dodging so I could see more detail on him, but it''s a nice macro image.</td>', 'Such a tiny bug!  he might benefit from a bit of dodging so I could see more detail on him, but it''s a nice macro image.', '2013-04-17 10:59:48.000000', NULL, 1),
(7022116, 1064738, 65234, '<td valign="top">Very cool little flower!  I really want more DOF or a slightly different angle so I can see more of it.</td>', 'Very cool little flower!  I really want more DOF or a slightly different angle so I can see more of it.', '2013-04-17 11:01:43.000000', NULL, 1),
(7022288, 1064716, 28276, '<td valign="top">While I am a big fan of fire, especially while camping on cold nights, there''s just not much here to drive my interest.  Zooming in to one of the lighter colored areas might have yielded more visual detail and a higher score.</td>', 'While I am a big fan of fire, especially while camping on cold nights, there''s just not much here to drive my interest.  Zooming in to one of the lighter colored areas might have yielded more visual detail and a higher score.', '2013-04-17 14:52:39.000000', NULL, 1),
(7022290, 1064403, 28276, '<td valign="top">Go closer.  Give me more detail on the subject, and less of the distracting elements of the background.</td>', 'Go closer.  Give me more detail on the subject, and less of the distracting elements of the background.', '2013-04-17 14:53:44.000000', NULL, 1),
(7022291, 1064435, 28276, '<td valign="top">I like the soft glow, but might have liked more light on the front details as well.  Lovely color, though.  I might have gone w/ a full square crop.</td>', 'I like the soft glow, but might have liked more light on the front details as well.  Lovely color, though.  I might have gone w/ a full square crop.', '2013-04-17 14:54:43.000000', NULL, 1),
(7022293, 1064670, 28276, '<td valign="top">A very sad photo (that''s not a bad thing).<br/> <br/>I think the light on the petal is a bit harsh which robbed it of needed detail.</td>', 'A very sad photo (that''s not a bad thing). I think the light on the petal is a bit harsh which robbed it of needed detail.', '2013-04-17 14:55:57.000000', NULL, 1),
(7022297, 1064439, 28276, '<td valign="top">Cool.  I find myself wanting to zoom in on our little friend here.  More difuse lighting and a tighter crop would have helped</td>', 'Cool.  I find myself wanting to zoom in on our little friend here.  More difuse lighting and a tighter crop would have helped', '2013-04-17 14:57:33.000000', NULL, 1),
(7022300, 1064275, 28276, '<td valign="top">Nice grab.  A circular polarizer might have helped the colors pop a bit more and softened the sunlight.  I also find bugs are more interesting when level (not sure why...)</td>', 'Nice grab.  A circular polarizer might have helped the colors pop a bit more and softened the sunlight.  I also find bugs are more interesting when level (not sure why...)', '2013-04-17 15:00:09.000000', NULL, 1),
(7022302, 1064333, 28276, '<td valign="top">I like this for it''s color and slightly odd framing.  Good job.</td>', 'I like this for it''s color and slightly odd framing.  Good job.', '2013-04-17 15:01:13.000000', NULL, 1),
(7022304, 1064268, 28276, '<td valign="top">I like how the drops look like they have bubbles.  I think it would help if we saw the edge of the leaf (leaf?) with a smoother background.  Maybe a touch less foreground blur...</td>', 'I like how the drops look like they have bubbles.  I think it would help if we saw the edge of the leaf (leaf?) with a smoother background.  Maybe a touch less foreground blur...', '2013-04-17 15:03:55.000000', NULL, 1),
(7022305, 1064585, 28276, '<td valign="top">Nailed it!  Ok, that was corny.  Sorry.<br/> <br/>Might have liked it closer to see more of the detail in the rust.  Also, we''d see less of slightly cluttered background.  Might have helped if it had been wet?</td>', 'Nailed it!  Ok, that was corny.  Sorry. Might have liked it closer to see more of the detail in the rust.  Also, we''d see less of slightly cluttered background.  Might have helped if it had been wet?', '2013-04-17 15:05:53.000000', NULL, 1),
(7022306, 1064545, 28276, '<td valign="top">Looks like the head of an alien swan creature.  Not much to critique, but then, not much happening.  I do like the sharp focus on the little white hairs...</td>', 'Looks like the head of an alien swan creature.  Not much to critique, but then, not much happening.  I do like the sharp focus on the little white hairs...', '2013-04-17 15:07:34.000000', NULL, 1),
(7022307, 1064042, 28276, '<td valign="top">I rather like this one.  I''d like to see what other angles you got on it...<br/> <br/>For this, I might have blurred out the stem in the bottom right and tried to tease out more contrast in the white part.  Otherwise, really cool.</td>', 'I rather like this one.  I''d like to see what other angles you got on it... For this, I might have blurred out the stem in the bottom right and tried to tease out more contrast in the white part.  Otherwise, really cool.', '2013-04-17 15:09:10.000000', NULL, 1),
(7022308, 1064711, 28276, '<td valign="top">This is very nice.  Background color works well to accent the eyes.</td>', 'This is very nice.  Background color works well to accent the eyes.', '2013-04-17 15:10:02.000000', NULL, 1),
(7022309, 1064605, 28276, '<td valign="top">Get me closer and give me one point of detail...</td>', 'Get me closer and give me one point of detail...', '2013-04-17 15:10:56.000000', NULL, 1),
(7022310, 1064586, 28276, '<td valign="top">Did you consider rotating this 90?  Also more detail in the center of the flower would have been nice.  I might have cropped to remove the flakes along the bottom of the frame, though.<br/> <br/>Nice color and detail otherwise.</td>', 'Did you consider rotating this 90?  Also more detail in the center of the flower would have been nice.  I might have cropped to remove the flakes along the bottom of the frame, though. Nice color and detail otherwise.', '2013-04-17 15:12:35.000000', NULL, 1),
(7022311, 1064261, 28276, '<td valign="top">Good framing.  I just want more...  something.</td>', 'Good framing.  I just want more...  something.', '2013-04-17 15:13:43.000000', NULL, 1),
(7022312, 1064695, 28276, '<td valign="top">Lighting falls a little flat, losing detail.  It becomes a jumble with no central focus.<br/> <br/>Cool bud, though...</td>', 'Lighting falls a little flat, losing detail.  It becomes a jumble with no central focus. Cool bud, though...', '2013-04-17 15:15:09.000000', NULL, 1),
(7022315, 1064456, 28276, '<td valign="top">Very nice.  Just would like a better view of the face and removal of some spots on the petals.</td>', 'Very nice.  Just would like a better view of the face and removal of some spots on the petals.', '2013-04-17 15:16:14.000000', NULL, 1),
(7022321, 1064606, 28276, '<td valign="top">I feel like I''m viewing a map of some poor town being swallowed by lava.  Which is cool...<br/> <br/>For this challenge, I wanna be closer though...  show me the streets...</td>', 'I feel like I''m viewing a map of some poor town being swallowed by lava.  Which is cool... For this challenge, I wanna be closer though...  show me the streets...', '2013-04-17 15:32:40.000000', NULL, 1),
(7022324, 1064453, 28276, '<td valign="top">This is kinda cool.  Love the blue.<br/> <br/>Just doesn''t feel macro, whatever it is...</td>', 'This is kinda cool.  Love the blue. Just doesn''t feel macro, whatever it is...', '2013-04-17 15:35:27.000000', NULL, 1),
(7022326, 1064457, 28276, '<td valign="top">Closer.  I want closer.  I''ve seen locks before...</td>', 'Closer.  I want closer.  I''ve seen locks before...', '2013-04-17 15:36:36.000000', NULL, 1),
(7022328, 1063978, 28276, '<td valign="top">Overall not a bad photo.  A contrasting color, more light, and a bit more detail on the shell would have helped.  Maybe use levels to boost the contrast?  Might have helped to be looking from a slightly different angle?</td>', 'Overall not a bad photo.  A contrasting color, more light, and a bit more detail on the shell would have helped.  Maybe use levels to boost the contrast?  Might have helped to be looking from a slightly different angle?', '2013-04-17 15:38:34.000000', NULL, 1),
(7022329, 1064525, 28276, '<td valign="top">Simple.  Plain.  Pure.  <br/> <br/>A lighter green and brighter background may have helped this a bit.</td>', 'Simple.  Plain.  Pure.   A lighter green and brighter background may have helped this a bit.', '2013-04-17 15:39:28.000000', NULL, 1),
(7022330, 1064740, 28276, '<td valign="top">I see you, too...<br/> <br/>Would have liked a bit more DOF, especially to bring out detail in the foot...<br/> <br/>Nice.</td>', 'I see you, too... Would have liked a bit more DOF, especially to bring out detail in the foot... Nice.', '2013-04-17 15:40:14.000000', NULL, 1),
(7022344, 1064674, 28276, '<td valign="top">Nice idea...  Would help if it looked like it was pushing out of the snow more than laying on top of it...  snow also looks a little dull, but that''s always hard to get right...</td>', 'Nice idea...  Would help if it looked like it was pushing out of the snow more than laying on top of it...  snow also looks a little dull, but that''s always hard to get right...', '2013-04-17 16:13:57.000000', NULL, 1),
(7022349, 1064048, 28276, '<td valign="top">Nice idea.  Love the color.  The blown &amp; bluish highlights distract a little.  DOF is a little too shallow.</td>', 'Nice idea.  Love the color.  The blown & bluish highlights distract a little.  DOF is a little too shallow.', '2013-04-17 16:15:55.000000', NULL, 1),
(7022351, 1064522, 28276, '<td valign="top">A great example of turtle portraiture.   Would have been really cool w/a nice bright green leaf in his mouth to provide contrast...</td>', 'A great example of turtle portraiture.   Would have been really cool w/a nice bright green leaf in his mouth to provide contrast...', '2013-04-17 16:17:20.000000', NULL, 1),
(7022354, 1064326, 28276, '<td valign="top">Nice composition and background.  Lighting is a tad harsh.  I find metals look good wet as it naturally boosts saturation...</td>', 'Nice composition and background.  Lighting is a tad harsh.  I find metals look good wet as it naturally boosts saturation...', '2013-04-17 16:19:09.000000', NULL, 1),
(7022372, 1063518, 112539, '<td valign="top">Your eye will go to the brightest spot first so my eye is drawn to the blurred flower first rather than the crisp macro flower..either there should have been black material behind the pink flower or the white flower should have been the macro crisp flower.</td>', 'Your eye will go to the brightest spot first so my eye is drawn to the blurred flower first rather than the crisp macro flower..either there should have been black material behind the pink flower or the white flower should have been the macro crisp flower.', '2013-04-17 18:12:04.000000', NULL, 1),
(7022373, 1064729, 112539, '<td valign="top">Interesting shot.</td>', 'Interesting shot.', '2013-04-17 18:14:20.000000', NULL, 1),
(7022446, 1064711, 159525, '<td valign="top">Nicely captured!</td>', 'Nicely captured!', '2013-04-17 19:39:01.000000', NULL, 1),
(7022447, 1064599, 159525, '<td valign="top">I love how mean this bug looks.  Great job!</td>', 'I love how mean this bug looks.  Great job!', '2013-04-17 19:39:21.000000', NULL, 1),
(7022448, 1064488, 159525, '<td valign="top">Beautiful macro!</td>', 'Beautiful macro!', '2013-04-17 19:39:33.000000', NULL, 1),
(7022449, 1064182, 159525, '<td valign="top">Creepy but good!</td>', 'Creepy but good!', '2013-04-17 19:39:44.000000', NULL, 1),
(7022450, 1064692, 159525, '<td valign="top">Soft and beautiful!</td>', 'Soft and beautiful!', '2013-04-17 19:39:54.000000', NULL, 1),
(7022451, 1064433, 159525, '<td valign="top">Love the water drops on the petals.</td>', 'Love the water drops on the petals.', '2013-04-17 19:40:08.000000', NULL, 1),
(7022460, 1064491, 112539, '<td valign="top">Beautiful flower but confused by the title...I see no bug.</td>', 'Beautiful flower but confused by the title...I see no bug.', '2013-04-17 19:58:15.000000', NULL, 1),
(7022461, 1064590, 112539, '<td valign="top">Bees are really hard to get because they don''t stay still but wish they were sharper. Maybe a higher shutter speed would have helped that.</td>', 'Bees are really hard to get because they don''t stay still but wish they were sharper. Maybe a higher shutter speed would have helped that.', '2013-04-17 19:59:36.000000', NULL, 1),
(7022462, 1064564, 112539, '<td valign="top">A darker background and backing down on the highlights or increasing contrast I think would have helped this image alot. I carry dark material in my car to place behind bright flowers like daffodils.</td>', 'A darker background and backing down on the highlights or increasing contrast I think would have helped this image alot. I carry dark material in my car to place behind bright flowers like daffodils.', '2013-04-17 20:01:29.000000', NULL, 1),
(7022463, 1064403, 112539, '<td valign="top">Your eye gravitates to the brightest spot of an image. The light leaves behind the leaf is very distracting. Try taking dark material and placing it on the ground under the leaf to make it pop and be the star attraction.</td>', 'Your eye gravitates to the brightest spot of an image. The light leaves behind the leaf is very distracting. Try taking dark material and placing it on the ground under the leaf to make it pop and be the star attraction.', '2013-04-17 20:04:15.000000', NULL, 1),
(7022465, 1064364, 112539, '<td valign="top">When doing macro you have to have something really crisp to draw the eye to.</td>', 'When doing macro you have to have something really crisp to draw the eye to.', '2013-04-17 20:05:40.000000', NULL, 1),
(7022502, 1064530, 112539, '<td valign="top">A shot like this needs to be crisp sharp to show what the drop is reflecting. Gotta use a tripod to do that as well as the proper settings.</td>', 'A shot like this needs to be crisp sharp to show what the drop is reflecting. Gotta use a tripod to do that as well as the proper settings.', '2013-04-17 21:20:42.000000', NULL, 1),
(7022506, 1064525, 112539, '<td valign="top">Nice detail on the daffodil. I would have cropped off the right part of a daffodil as it is distracting.</td>', 'Nice detail on the daffodil. I would have cropped off the right part of a daffodil as it is distracting.', '2013-04-17 21:22:00.000000', NULL, 1),
(7022509, 1064439, 112539, '<td valign="top">Love the close sharp detail of the bug but I would have cropped it tighter as the bright area of the photo at the top draws the eye away from the great job you did on the bug.</td>', 'Love the close sharp detail of the bug but I would have cropped it tighter as the bright area of the photo at the top draws the eye away from the great job you did on the bug.', '2013-04-17 21:24:40.000000', NULL, 1),
(7022511, 1064326, 112539, '<td valign="top">Really liked this! #1 because it wasn''t a flower or a bug...#2 because it kept my interest with the way the wire intertwined. The broken peace looks like a snake wrapped around a stick. Very creative shot. I like the less usual for competition. Well done.</td>', 'Really liked this! #1 because it wasn''t a flower or a bug...#2 because it kept my interest with the way the wire intertwined. The broken peace looks like a snake wrapped around a stick. Very creative shot. I like the less usual for competition. Well done.', '2013-04-17 21:48:46.000000', NULL, 1),
(7022513, 1064333, 112539, '<td valign="top">Beautiful detail!</td>', 'Beautiful detail!', '2013-04-17 21:51:32.000000', NULL, 1),
(7022514, 1064224, 112539, '<td valign="top">Need the head to be the sharpest area for me to score higher.</td>', 'Need the head to be the sharpest area for me to score higher.', '2013-04-17 21:56:01.000000', NULL, 1),
(7022518, 1063761, 124982, '<td valign="top">Most beautiful..you really captured this wonderfully!</td>', 'Most beautiful..you really captured this wonderfully!', '2013-04-17 22:21:49.000000', NULL, 1),
(7022519, 1064665, 124982, '<td valign="top">Quite lovely, my good man! Looks even better second time round!</td>', 'Quite lovely, my good man! Looks even better second time round!', '2013-04-17 22:22:16.000000', NULL, 1),
(7022520, 1064048, 159525, '<td valign="top">Nice find!</td>', 'Nice find!', '2013-04-17 22:22:49.000000', NULL, 1),
(7022522, 1064547, 159525, '<td valign="top">Beautiful capture!</td>', 'Beautiful capture!', '2013-04-17 22:23:05.000000', NULL, 1),
(7022523, 1064512, 124982, '<td valign="top">Exceptionally beautiful with great detail and sharpness. Well captured!! Wonder if you''re getting dinged by the DNMC crowd for this now being a "true" macro?</td>', 'Exceptionally beautiful with great detail and sharpness. Well captured!! Wonder if you''re getting dinged by the DNMC crowd for this now being a "true" macro?', '2013-04-17 22:23:34.000000', NULL, 1),
(7022524, 1064523, 159525, '<td valign="top">This have some really great texture!</td>', 'This have some really great texture!', '2013-04-17 22:23:35.000000', NULL, 1),
(7022525, 1064261, 159525, '<td valign="top">Fantastic!  I love the simplicity of this image.</td>', 'Fantastic!  I love the simplicity of this image.', '2013-04-17 22:23:56.000000', NULL, 1),
(7022531, 1064333, 124982, '<td valign="top">Gorgeous lighting!! Wish it was cropped a tad closer so we could see some of the lovely detail in the fronds.</td>', 'Gorgeous lighting!! Wish it was cropped a tad closer so we could see some of the lovely detail in the fronds.', '2013-04-17 22:31:33.000000', NULL, 1),
(7022532, 1064287, 124982, '<td valign="top">Good golly, this is fantastic! Quite love the color and sharpness. Would love to know how you shot this (lens and if flash or natural lighting was use?).<br/> <br/>EDIT: just finished voting, and this is my top entry and sole 9.</td>', 'Good golly, this is fantastic! Quite love the color and sharpness. Would love to know how you shot this (lens and if flash or natural lighting was use?). EDIT: just finished voting, and this is my top entry and sole 9.', '2013-04-17 22:33:05.000000', NULL, 1),
(7022533, 1063704, 124982, '<td valign="top">Quite magnificent! Just lovely tones and shades and shadows! Gorgeous!<br/> <br/>EDIT: just finished voting and this is in my Top 3!</td>', 'Quite magnificent! Just lovely tones and shades and shadows! Gorgeous! EDIT: just finished voting and this is in my Top 3!', '2013-04-17 22:33:32.000000', NULL, 1),
(7022534, 1064648, 124982, '<td valign="top">Absolutely splendid sharpness and clarity on this! Just love the detail and tones!<br/> <br/>EDIT: just finished voting and this is in my Top 3</td>', 'Absolutely splendid sharpness and clarity on this! Just love the detail and tones! EDIT: just finished voting and this is in my Top 3', '2013-04-17 22:33:39.000000', NULL, 1),
(7022554, 1064669, 40391, '<td valign="top">Beautiful details and colour. Wonderful capture.</td>', 'Beautiful details and colour. Wonderful capture.', '2013-04-17 23:19:10.000000', NULL, 1),
(7022575, 1064287, 40391, '<td valign="top">Superb image. Those colours and the details - Wow!</td>', 'Superb image. Those colours and the details - Wow!', '2013-04-17 23:34:26.000000', NULL, 1),
(7022592, 1063376, 77683, '<td valign="top">I don''t think any one element of this shot - high contrast, the leaf texture, fly silhouette..,... - makes it a great capture. It''s all of the elements in harmony that make it. Well done.</td>', 'I don''t think any one element of this shot - high contrast, the leaf texture, fly silhouette..,... - makes it a great capture. It''s all of the elements in harmony that make it. Well done.', '2013-04-18 00:02:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7022593, 1064438, 77683, '<td valign="top">incredibly simple elements come together to make a very pleasing scene. BTW -- how did you get the drop like that? It must have been in motion?</td>', 'incredibly simple elements come together to make a very pleasing scene. BTW -- how did you get the drop like that? It must have been in motion?', '2013-04-18 00:03:32.000000', NULL, 1),
(7022594, 1064732, 77683, '<td valign="top">REALLY like this one - amazing composition and details. Nice use of Negative Space - not something that comes naturally when trying to get as ''close up'' as possible (at least for me). 10.<br/> <br/>(This could be a movie poster)</td>', 'REALLY like this one - amazing composition and details. Nice use of Negative Space - not something that comes naturally when trying to get as ''close up'' as possible (at least for me). 10. (This could be a movie poster)', '2013-04-18 00:03:47.000000', NULL, 1),
(7022595, 1064711, 77683, '<td valign="top">At first the DOF bothered me - the back half of the fly being out of focus felt wrong. BUT on second look, I think the DOF is an awesome choice - it makes the fly feel like it might be the same size as I am. Lots of fun.</td>', 'At first the DOF bothered me - the back half of the fly being out of focus felt wrong. BUT on second look, I think the DOF is an awesome choice - it makes the fly feel like it might be the same size as I am. Lots of fun.', '2013-04-18 00:05:17.000000', NULL, 1),
(7022596, 1064393, 77683, '<td valign="top">Great story told here.</td>', 'Great story told here.', '2013-04-18 00:05:51.000000', NULL, 1),
(7022597, 1064709, 77683, '<td valign="top">Good decision with underexposure.</td>', 'Good decision with underexposure.', '2013-04-18 00:07:43.000000', NULL, 1),
(7022683, 1063285, 47597, '<td valign="top">It doesn''t wow me. :(</td>', 'It doesn''t wow me. :(', '2013-04-18 10:01:39.000000', NULL, 1),
(7022684, 1064726, 47597, '<td valign="top">Very nice and sharp. The drops of water on the caterpillar are nice!</td>', 'Very nice and sharp. The drops of water on the caterpillar are nice!', '2013-04-18 10:03:03.000000', NULL, 1),
(7022785, 1064342, 118457, '<td valign="top">Good one!</td>', 'Good one!', '2013-04-18 15:11:26.000000', NULL, 1),
(7022788, 1064333, 118457, '<td valign="top">like colors</td>', 'like colors', '2013-04-18 15:12:38.000000', NULL, 1),
(7022811, 1064453, 3102, '<td valign="top">Cool shot, but isn''t what I''d consider to be a macro.</td>', 'Cool shot, but isn''t what I''d consider to be a macro.', '2013-04-18 16:26:51.000000', NULL, 1),
(7022813, 1064499, 3102, '<td valign="top">Um... it doesn''t get much further from being a "macro" than this...</td>', 'Um... it doesn''t get much further from being a "macro" than this...', '2013-04-18 16:30:12.000000', NULL, 1),
(7022824, 1064738, 28276, '<td valign="top">More of the flower needs to be in focus and I would find a more pleasing color for the background.  Another angle might have helped...</td>', 'More of the flower needs to be in focus and I would find a more pleasing color for the background.  Another angle might have helped...', '2013-04-18 17:08:41.000000', NULL, 1),
(7022825, 1064673, 28276, '<td valign="top">Love this detail and toning.  A nice fat spider in the middle would be nice.<br/> <br/>A little more DOF would have been nice.</td>', 'Love this detail and toning.  A nice fat spider in the middle would be nice. A little more DOF would have been nice.', '2013-04-18 17:09:46.000000', NULL, 1),
(7022826, 1064526, 28276, '<td valign="top">Lovely.  Nice color and framing.  Good DOF.   A little more contrast might have helped...  Especially in the yellow.</td>', 'Lovely.  Nice color and framing.  Good DOF.   A little more contrast might have helped...  Especially in the yellow.', '2013-04-18 17:11:23.000000', NULL, 1),
(7022827, 1064669, 28276, '<td valign="top">Very interesting capture.  Too bad you could get rid of the dust/pollon on the eyes.<br/> <br/>A little more light on the underside might have set off the face a little better.</td>', 'Very interesting capture.  Too bad you could get rid of the dust/pollon on the eyes. A little more light on the underside might have set off the face a little better.', '2013-04-18 17:12:53.000000', NULL, 1),
(7022828, 1064725, 28276, '<td valign="top">Nice color and framing.  Use of the water was a nice detail.<br/> <br/>Light seems a bit harsh.  Circular Polarizer might have helped.  You can shade shots w/ a single sheet of white paper to soften the light a bit...</td>', 'Nice color and framing.  Use of the water was a nice detail. Light seems a bit harsh.  Circular Polarizer might have helped.  You can shade shots w/ a single sheet of white paper to soften the light a bit...', '2013-04-18 17:14:28.000000', NULL, 1),
(7022829, 1064633, 28276, '<td valign="top">I like the framing and color a lot.  It makes me want to look at it...  Enjoy the detail in the ends of the pedals.  a little more DOF would be nice, but I really think I keep looking in it to find something and don''t.  But I keep looking...</td>', 'I like the framing and color a lot.  It makes me want to look at it...  Enjoy the detail in the ends of the pedals.  a little more DOF would be nice, but I really think I keep looking in it to find something and don''t.  But I keep looking...', '2013-04-18 17:16:41.000000', NULL, 1),
(7022830, 1064599, 28276, '<td valign="top">Seems a little dark and the focus is a little bit too far in front of the face...  Otherwise a very cool capture...</td>', 'Seems a little dark and the focus is a little bit too far in front of the face...  Otherwise a very cool capture...', '2013-04-18 17:17:36.000000', NULL, 1),
(7022835, 1063426, 28276, '<td valign="top">I actually have a shot of this flower in my outtakes for this challenge.  Love the blue...  Green feels a bit too dark and I''m not sure I like the framing.  I find myself wanting the flower on top, or maybe rotated into a corner...</td>', 'I actually have a shot of this flower in my outtakes for this challenge.  Love the blue...  Green feels a bit too dark and I''m not sure I like the framing.  I find myself wanting the flower on top, or maybe rotated into a corner...', '2013-04-18 17:34:58.000000', NULL, 1),
(7022836, 1064475, 131419, '<td valign="top">Nice composition</td>', 'Nice composition', '2013-04-18 17:36:15.000000', NULL, 1),
(7022837, 1064512, 28276, '<td valign="top">I like the eye and water drop.  Something in the PP seems false to me, especially around the neck and end of the bill.  Though I like the image overall, it doesn''t really scream macro to me.</td>', 'I like the eye and water drop.  Something in the PP seems false to me, especially around the neck and end of the bill.  Though I like the image overall, it doesn''t really scream macro to me.', '2013-04-18 17:37:45.000000', NULL, 1),
(7022838, 1064665, 28276, '<td valign="top">I like the lighting and framing on this.  Focus is good.  More contrast in the yellow might have helped pull my eye in more...</td>', 'I like the lighting and framing on this.  Focus is good.  More contrast in the yellow might have helped pull my eye in more...', '2013-04-18 17:39:08.000000', NULL, 1),
(7022839, 1064156, 28276, '<td valign="top">A face only a monster could love...  Very nice contrast w/ the color in the flower.  Works well.  Would have loved more DOF to get the horn and back of the eye lid in more detail.<br/> <br/>Great job.</td>', 'A face only a monster could love...  Very nice contrast w/ the color in the flower.  Works well.  Would have loved more DOF to get the horn and back of the eye lid in more detail. Great job.', '2013-04-18 17:40:30.000000', NULL, 1),
(7022840, 1064692, 131419, '<td valign="top">Beautiful</td>', 'Beautiful', '2013-04-18 17:40:55.000000', NULL, 1),
(7022841, 1064689, 28276, '<td valign="top">Good colors and very good detail where you want it...  Might want to think about a different crop/framing.  Get your subject off center or keep it dead center and square crop.  Harsh lighting on the edge of the pedals is somewhat distracting...</td>', 'Good colors and very good detail where you want it...  Might want to think about a different crop/framing.  Get your subject off center or keep it dead center and square crop.  Harsh lighting on the edge of the pedals is somewhat distracting...', '2013-04-18 17:42:14.000000', NULL, 1),
(7022843, 1064084, 131419, '<td valign="top">He is gorgeous, well captured</td>', 'He is gorgeous, well captured', '2013-04-18 17:42:55.000000', NULL, 1),
(7022844, 1063376, 28276, '<td valign="top">The heavy border is distracting to my eye...  It gives too much weight to the black portions of the lower right of the image.<br/> <br/>Otherwise this is a really cool photo.</td>', 'The heavy border is distracting to my eye...  It gives too much weight to the black portions of the lower right of the image. Otherwise this is a really cool photo.', '2013-04-18 17:43:39.000000', NULL, 1),
(7022845, 1063285, 28276, '<td valign="top">I just really not sure what you want me to see here.  Certainly not a macro unless that board is just far smaller than this image leads me to believe.</td>', 'I just really not sure what you want me to see here.  Certainly not a macro unless that board is just far smaller than this image leads me to believe.', '2013-04-18 17:46:41.000000', NULL, 1),
(7022846, 1064564, 28276, '<td valign="top">Colors are nice, but it could really use some contrast to bring out the details of those areas in sharp focus.  As is, the sharp areas blind into the softer areas, so my eye doesn''t land anywhere...</td>', 'Colors are nice, but it could really use some contrast to bring out the details of those areas in sharp focus.  As is, the sharp areas blind into the softer areas, so my eye doesn''t land anywhere...', '2013-04-18 17:48:12.000000', NULL, 1),
(7022847, 1063846, 131419, '<td valign="top">Great lighting , really like this</td>', 'Great lighting , really like this', '2013-04-18 17:48:20.000000', NULL, 1),
(7022848, 1064621, 28276, '<td valign="top">Cute.  Nice lighting and color.  Background blur is nice, but a little busy.<br/> <br/>Wish you''d gotten the shot before he was partially hidden by the foreground element...</td>', 'Cute.  Nice lighting and color.  Background blur is nice, but a little busy. Wish you''d gotten the shot before he was partially hidden by the foreground element...', '2013-04-18 17:49:12.000000', NULL, 1),
(7022849, 1064590, 28276, '<td valign="top">Cool flower and the bees are nice.  Just really busy.  maybe focusing in on one small cluster of blooms and one bee would have helped?  Color seems a bit dark/flat to me as well.</td>', 'Cool flower and the bees are nice.  Just really busy.  maybe focusing in on one small cluster of blooms and one bee would have helped?  Color seems a bit dark/flat to me as well.', '2013-04-18 17:50:21.000000', NULL, 1),
(7022850, 1064617, 28276, '<td valign="top">In the abstract, I really like this.  It''s a picture of one thing that looks like something else at first glance.  Cool.<br/> <br/>I think I''d like to see a little more contrast maybe...  What would it look like wet?  Like after a rain?  I''d also like to know just how big it is...</td>', 'In the abstract, I really like this.  It''s a picture of one thing that looks like something else at first glance.  Cool. I think I''d like to see a little more contrast maybe...  What would it look like wet?  Like after a rain?  I''d also like to know just how big it is...', '2013-04-18 17:52:51.000000', NULL, 1),
(7022852, 1064098, 28276, '<td valign="top">In macro, I want to see something small, from an angle I''ve never considered...  This is not that...  What if you had focused on just one part of this?  Just the white/blue square?</td>', 'In macro, I want to see something small, from an angle I''ve never considered...  This is not that...  What if you had focused on just one part of this?  Just the white/blue square?', '2013-04-18 17:55:26.000000', NULL, 1),
(7022854, 1064364, 28276, '<td valign="top">I find Tulips are hard to make interesting, especially the darker ones...  Focus is on the right spot, but DOF is too shallow and the light is washing out all your detail...</td>', 'I find Tulips are hard to make interesting, especially the darker ones...  Focus is on the right spot, but DOF is too shallow and the light is washing out all your detail...', '2013-04-18 17:57:17.000000', NULL, 1),
(7022855, 1064726, 28276, '<td valign="top">Once you''ve reached the top, there''s no where to go but back down to repeat the climb...<br/> <br/>Nice capture.  Good focus.  More contrasting color in the background might have made it more interesting...</td>', 'Once you''ve reached the top, there''s no where to go but back down to repeat the climb... Nice capture.  Good focus.  More contrasting color in the background might have made it more interesting...', '2013-04-18 17:58:59.000000', NULL, 1),
(7022856, 1064517, 28276, '<td valign="top">Very nice.  Interesting title. (I''ve submitted too late to update the title before...)<br/> <br/>Very cool subject and nice detail.  Focus is great.  What I wouldnt'' give for some fill light on his face...</td>', 'Very nice.  Interesting title. (I''ve submitted too late to update the title before...) Very cool subject and nice detail.  Focus is great.  What I wouldnt'' give for some fill light on his face...', '2013-04-18 18:00:27.000000', NULL, 1),
(7022857, 1064491, 28276, '<td valign="top">I could see this as an accent wall in a little girls room.  Very nice.<br/> <br/>A little more light on the very bottom to soften up the black/dark green would have been nice.</td>', 'I could see this as an accent wall in a little girls room.  Very nice. A little more light on the very bottom to soften up the black/dark green would have been nice.', '2013-04-18 18:01:31.000000', NULL, 1),
(7022969, 1064523, 60495, '<td valign="top">Pretty cool veins in the leaf and the colors are nice but overall the scene seems cluttered to me. Maybe if the image was focused on just one topic I may have liked it a little more, still overall not bad I give it a 6</td>', 'Pretty cool veins in the leaf and the colors are nice but overall the scene seems cluttered to me. Maybe if the image was focused on just one topic I may have liked it a little more, still overall not bad I give it a 6', '2013-04-18 23:11:35.000000', NULL, 1),
(7022970, 1064480, 60495, '<td valign="top">Pretty rose, this is like what I attempted with my very first image entry in DPC, you have done what I had hoped when I attempted my full frame rose, nicely done!</td>', 'Pretty rose, this is like what I attempted with my very first image entry in DPC, you have done what I had hoped when I attempted my full frame rose, nicely done!', '2013-04-18 23:13:54.000000', NULL, 1),
(7022971, 1064682, 60495, '<td valign="top">To me a tighter crop may have helped, I find the upper part of the flower and the upper part of the image to be a huge distraction against the pretty color of the flower.</td>', 'To me a tighter crop may have helped, I find the upper part of the flower and the upper part of the image to be a huge distraction against the pretty color of the flower.', '2013-04-18 23:17:11.000000', NULL, 1),
(7022972, 1064502, 60495, '<td valign="top">Interesting subject, love the ice hanging off and the nice bokeh in the back ground. The only down side is the blurred twig coming out of the front but overall a pleasing image.</td>', 'Interesting subject, love the ice hanging off and the nice bokeh in the back ground. The only down side is the blurred twig coming out of the front but overall a pleasing image.', '2013-04-18 23:19:17.000000', NULL, 1),
(7022975, 1064324, 60495, '<td valign="top">One of those images were I am not sure what I am supposed to look at, I find the colors to be somewhat interesting but then my eyes go to the black and white blurry area which makes the image seem confusing.  As an abstract image it falls short of making me personally want this on my wall but may appeal to others. Good luck in the challenge and I look forward to seeing the thoughts others may have about this image.</td>', 'One of those images were I am not sure what I am supposed to look at, I find the colors to be somewhat interesting but then my eyes go to the black and white blurry area which makes the image seem confusing.  As an abstract image it falls short of making me personally want this on my wall but may appeal to others. Good luck in the challenge and I look forward to seeing the thoughts others may have about this image.', '2013-04-18 23:28:54.000000', NULL, 1),
(7022976, 1064732, 60495, '<td valign="top">An interesting death!</td>', 'An interesting death!', '2013-04-18 23:29:26.000000', NULL, 1),
(7022977, 1063970, 60495, '<td valign="top">Nicely done, I wish I could get them to hold in one place long enough to get a shot like this.</td>', 'Nicely done, I wish I could get them to hold in one place long enough to get a shot like this.', '2013-04-18 23:30:13.000000', NULL, 1),
(7022980, 1064335, 60495, '<td valign="top">No one can say this is not Macro, not sure what it is but kind of looks like sand paper up close and personal.</td>', 'No one can say this is not Macro, not sure what it is but kind of looks like sand paper up close and personal.', '2013-04-18 23:31:51.000000', NULL, 1),
(7022984, 1064156, 60495, '<td valign="top">Great focus on the eye, wish the DOF was just a hair wider to catch the nose too but some times you just can''t have it all. 6</td>', 'Great focus on the eye, wish the DOF was just a hair wider to catch the nose too but some times you just can''t have it all. 6', '2013-04-18 23:34:08.000000', NULL, 1),
(7022989, 1064734, 60495, '<td valign="top">When ever I find myself wondering what the photographer wanted me to see and can not find any subject to connect with I get a little uneasy about how to vote, I want to like this image because it leads me through to opening but when I go through I just do not find where I should go from there, I guess in a sense that causes me to stop and ponder the image but when I do I am still not sure whether to like it or not. If I look at the image purely as an abstract it does not really work for me but the fact that it has me baffled has created a weird interest so I guess well done, I think, maybe...</td>', 'When ever I find myself wondering what the photographer wanted me to see and can not find any subject to connect with I get a little uneasy about how to vote, I want to like this image because it leads me through to opening but when I go through I just do not find where I should go from there, I guess in a sense that causes me to stop and ponder the image but when I do I am still not sure whether to like it or not. If I look at the image purely as an abstract it does not really work for me but the fact that it has me baffled has created a weird interest so I guess well done, I think, maybe...', '2013-04-18 23:45:44.000000', NULL, 1),
(7022991, 1064084, 60495, '<td valign="top">If you kiss the screen he will turn into a prince, or is that hit like and see what happens, this new fangled internet thingy has me all confused!</td>', 'If you kiss the screen he will turn into a prince, or is that hit like and see what happens, this new fangled internet thingy has me all confused!', '2013-04-18 23:47:58.000000', NULL, 1),
(7022992, 1064724, 60495, '<td valign="top">Nice image but your model is butt ugly..lol</td>', 'Nice image but your model is butt ugly..lol', '2013-04-18 23:48:35.000000', NULL, 1),
(7022993, 1064606, 60495, '<td valign="top">I love the contrast of the two colors and the simplicity of the shot, well done.</td>', 'I love the contrast of the two colors and the simplicity of the shot, well done.', '2013-04-18 23:49:33.000000', NULL, 1),
(7022995, 1064692, 60495, '<td valign="top">Pretty rose, nicely done</td>', 'Pretty rose, nicely done', '2013-04-18 23:50:00.000000', NULL, 1),
(7022997, 1064526, 60495, '<td valign="top">Great detail and color, the DOF is nicely handled.</td>', 'Great detail and color, the DOF is nicely handled.', '2013-04-18 23:50:37.000000', NULL, 1),
(7023000, 1064307, 60495, '<td valign="top">Nice contrast in colors and the lady bug makes a nice topper.</td>', 'Nice contrast in colors and the lady bug makes a nice topper.', '2013-04-18 23:51:22.000000', NULL, 1),
(7023003, 1064596, 60495, '<td valign="top">Love how you got up close and personal.</td>', 'Love how you got up close and personal.', '2013-04-18 23:52:58.000000', NULL, 1),
(7023005, 1064393, 60495, '<td valign="top">Hands of a hard worker!</td>', 'Hands of a hard worker!', '2013-04-18 23:53:43.000000', NULL, 1),
(7023007, 1064726, 60495, '<td valign="top">On top of the world, nice detail, interesting setting.</td>', 'On top of the world, nice detail, interesting setting.', '2013-04-18 23:54:37.000000', NULL, 1),
(7023012, 1064738, 60495, '<td valign="top">A little too much going on in this one for my taste, would have liked it more if you would have gotten closer and chose a section of the flower to concentrate on, to me the background does not add anything of interest to the image and would have been better left out.</td>', 'A little too much going on in this one for my taste, would have liked it more if you would have gotten closer and chose a section of the flower to concentrate on, to me the background does not add anything of interest to the image and would have been better left out.', '2013-04-18 23:57:55.000000', NULL, 1),
(7023016, 1064326, 60495, '<td valign="top">I love this, simple subject with a complimentary background with a nice creamy Bokeh.</td>', 'I love this, simple subject with a complimentary background with a nice creamy Bokeh.', '2013-04-18 23:59:14.000000', NULL, 1),
(7023025, 1064475, 60495, '<td valign="top">Nicely done, very up close and personal. DOF is pretty nice with a nice combination of in focus and blur, the sharp areas are nicely placed on the seeds and the back ground works to highlight the fibers.</td>', 'Nicely done, very up close and personal. DOF is pretty nice with a nice combination of in focus and blur, the sharp areas are nicely placed on the seeds and the back ground works to highlight the fibers.', '2013-04-19 00:03:02.000000', NULL, 1),
(7023029, 1064438, 60495, '<td valign="top">Love the water drop and the lines of the leaves, nicely done</td>', 'Love the water drop and the lines of the leaves, nicely done', '2013-04-19 00:04:47.000000', NULL, 1),
(7023032, 1064268, 60495, '<td valign="top">The large drop in the center was the first drop to catch my eye so I just wish the DOF would have been back just slightly to catch a few more drops but still a nice image.</td>', 'The large drop in the center was the first drop to catch my eye so I just wish the DOF would have been back just slightly to catch a few more drops but still a nice image.', '2013-04-19 00:09:05.000000', NULL, 1),
(7023033, 1064575, 60495, '<td valign="top">Pretty cool image, I love the way the tongue is sharp but yet disappears into the background in a way that looks natural. The focus on the head is dead on and really well done.</td>', 'Pretty cool image, I love the way the tongue is sharp but yet disappears into the background in a way that looks natural. The focus on the head is dead on and really well done.', '2013-04-19 00:14:05.000000', NULL, 1),
(7023034, 1064545, 60495, '<td valign="top">Really Beautiful, fantastic flower offset with a nice background, well done. 10</td>', 'Really Beautiful, fantastic flower offset with a nice background, well done. 10', '2013-04-19 00:19:52.000000', NULL, 1),
(7023141, 1064717, 56167, '<td valign="top">what nice deep colour,</td>', 'what nice deep colour,', '2013-04-19 06:32:24.000000', NULL, 1),
(7023160, 1064513, 67258, '<td valign="top">Perhaps not a macro, but certainly a close-up - and oh, so  sweet :)</td>', 'Perhaps not a macro, but certainly a close-up - and oh, so  sweet :)', '2013-04-19 07:34:27.000000', NULL, 1),
(7023161, 1064466, 67258, '<td valign="top">What an intriguing flower - the outer petals look like fleece.  Thank you for showing me something I have never seen before.</td>', 'What an intriguing flower - the outer petals look like fleece.  Thank you for showing me something I have never seen before.', '2013-04-19 07:35:43.000000', NULL, 1),
(7023425, 1064362, 114225, '<td valign="top">Always nice to see fresh rain on a fresh leaf. I like the way the purple background offsets the green.</td>', 'Always nice to see fresh rain on a fresh leaf. I like the way the purple background offsets the green.', '2013-04-19 16:28:05.000000', NULL, 1),
(7023426, 1064737, 114225, '<td valign="top">Cool looking subject. This is a photo screaming for the photo stacking technique. If you have never used it, look it up, it''s cool :)</td>', 'Cool looking subject. This is a photo screaming for the photo stacking technique. If you have never used it, look it up, it''s cool :)', '2013-04-19 16:28:42.000000', NULL, 1),
(7023428, 1064635, 114225, '<td valign="top">Great find. I could maybe use a bit more brightness.</td>', 'Great find. I could maybe use a bit more brightness.', '2013-04-19 16:29:13.000000', NULL, 1),
(7023430, 1064728, 114225, '<td valign="top">Great time of day to take this. The highlighting style light is very nice.</td>', 'Great time of day to take this. The highlighting style light is very nice.', '2013-04-19 16:30:39.000000', NULL, 1),
(7023431, 1064453, 114225, '<td valign="top">I like the abstract nature of this.</td>', 'I like the abstract nature of this.', '2013-04-19 16:31:13.000000', NULL, 1),
(7023433, 1063761, 114225, '<td valign="top">Wow, that is just fantastic! When the ice hit here, I wanted to get something, but would have never gotten anything this cool.</td>', 'Wow, that is just fantastic! When the ice hit here, I wanted to get something, but would have never gotten anything this cool.', '2013-04-19 16:32:18.000000', NULL, 1),
(7023434, 1064648, 114225, '<td valign="top">Beautiful light and shadows.</td>', 'Beautiful light and shadows.', '2013-04-19 16:33:02.000000', NULL, 1),
(7023436, 1064439, 114225, '<td valign="top">I really like how the light highlights the subject.</td>', 'I really like how the light highlights the subject.', '2013-04-19 16:34:47.000000', NULL, 1),
(7023441, 1064689, 114225, '<td valign="top">I really like the abundance of detail on display.</td>', 'I really like the abundance of detail on display.', '2013-04-19 16:36:49.000000', NULL, 1),
(7023442, 1064156, 114225, '<td valign="top">I really like the way this comes together. The different elements pull together nicely.</td>', 'I really like the way this comes together. The different elements pull together nicely.', '2013-04-19 16:38:58.000000', NULL, 1),
